DROP TABLE IF EXISTS `mobile_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mobile_sessions` (
  `session_id` varchar(36) NOT NULL,
  `machine_id` varchar(100) DEFAULT NULL,
  `status` enum('waiting','active','expired') DEFAULT 'waiting',
  `work_centre_id` int DEFAULT NULL,
  `emp_id` int DEFAULT NULL,
  `emp_code` varchar(50) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `activated_at` timestamp NULL DEFAULT NULL,
  `active_machine_key` varchar(100) GENERATED ALWAYS AS ((case when (`status` = _utf8mb4'active') then `machine_id` else NULL end)) STORED,
  `active_emp_key` varchar(50) GENERATED ALWAYS AS ((case when (`status` = _utf8mb4'active') then `emp_code` else NULL end)) STORED,
  PRIMARY KEY (`session_id`),
  UNIQUE KEY `uniq_active_machine` (`active_machine_key`),
  UNIQUE KEY `uniq_active_emp` (`active_emp_key`),
  KEY `idx_session_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
